using System.Net;
using System.Net.Http.Json;
using SolidOps.UM.Application;
using SolidOps.UM.Domain;

namespace SolidOps.UM.Tests;

[TestClass]
public sealed class TeamTests : ApiTestBase
{
    [TestMethod]
    public async Task TeamGoesThroughTheWholeCrudAndSynchronizesItsMembers()
    {
        await AddUsersAsync("ada@example.com", "bob@example.com", "cy@example.com");
        var created = await PostAsync<TeamDto>("/teams", NewTeam("Core", Member("ada@example.com", true), Member("bob@example.com", false)));
        Assert.HasCount(2, created.Members);

        var ada = created.Members.Single(x => x.UserEmail == "ada@example.com");
        var update = NewTeam("Core 2", new TeamMemberInput { Id = ada.Id, UserEmail = "ada@example.com", IsOwner = true }, Member("cy@example.com", false));
        var response = await Client.PutAsJsonAsync($"/teams/{created.Id}", update);
        Assert.AreEqual(HttpStatusCode.OK, response.StatusCode);
        var updated = (await response.Content.ReadFromJsonAsync<TeamDto>())!;
        Assert.AreEqual("Core 2", updated.Name);
        CollectionAssert.AreEquivalent(new[] { "ada@example.com", "cy@example.com" }, updated.Members.Select(x => x.UserEmail).ToArray());
        Assert.AreEqual(ada.Id, updated.Members.Single(x => x.UserEmail == "ada@example.com").Id);

        var read = await Client.GetFromJsonAsync<TeamDto>($"/teams/{created.Id}");
        Assert.HasCount(2, read!.Members);

        var page = await Client.GetFromJsonAsync<Page<TeamDto>>("/teams");
        Assert.HasCount(1, page!.Items);

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/teams/{created.Id}")).StatusCode);

        await Client.PutAsJsonAsync($"/teams/{created.Id}", NewTeam("Core 2"));
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/teams/{created.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/teams/{created.Id}")).StatusCode);
    }

    [TestMethod]
    public async Task TeamWithoutMembersIsAllowed()
